'use strict';

const path = require('path');
const cds = require('@sap/cds');
const { UPGRADE_DIR, REPORT_FILE, FINDINGS_FILE } = require('../../constants');
const { parsePomXml, getPomPropertyValue } = require('../../util/pom');
const { serializeToYaml } = require('./utils/yaml');

function generate(ctx) {
  if (!ctx.shouldReport) return;
  const { findings = [], manualReviewRules = [] } = ctx.analysis || {};
  if (findings.length === 0 && manualReviewRules.length === 0) return;
  const outputDir = path.join(cds.root, UPGRADE_DIR);
  cds.utils.fs.mkdirSync(outputDir, { recursive: true });
  const lines = buildFullReport(ctx);
  cds.utils.fs.writeFileSync(path.join(outputDir, REPORT_FILE), lines.join('\n') + '\n');
  if (ctx.analysis) {
    writeFindings(ctx, outputDir);
  }
}

function buildFullReport(ctx) {
  const lines = [];
  appendHeader(lines);
  appendJavaConfig(lines, ctx);
  appendProcessedFiles(lines, ctx);
  appendAnalysis(lines, ctx);
  appendManualReview(lines, ctx);
  appendWarnings(lines, ctx);
  return lines;
}

function appendHeader(lines) {
  lines.push('# cds Upgrade Report');
  lines.push('');
  lines.push(`Generated: ${new Date().toISOString()}`);
  lines.push('');
}

function appendJavaConfig(lines, ctx) {
  const pomXmlFiles = ctx.project?.pomXmlFiles || [];
  if (!pomXmlFiles.length) return;
  lines.push('## Java Configuration');
  lines.push('');
  for (const pomPath of pomXmlFiles) {
    const pom = parsePomXml(pomPath);
    const properties = pom?.properties?.[0];
    lines.push(`### ${path.relative(cds.root, pomPath)}`);
    lines.push('');
    if (!properties) { lines.push('*No properties found*'); lines.push(''); continue; }
    for (const prop of ['cds.services.version', 'cds.install-cdsdk.version', 'spring.boot.version', 'jdk.version']) {
      const value = getPomPropertyValue(pom, prop);
      if (value !== null) {
        lines.push(`- **${prop}**: ${value}`);
      }
    }
    lines.push('');
  }
}

function appendProcessedFiles(lines, ctx) {
  const packageJsonFiles = ctx.project?.packageJsonFiles || [];
  const pomXmlFiles = ctx.project?.pomXmlFiles || [];
  if (!packageJsonFiles.length && !pomXmlFiles.length) return;
  lines.push('## Processed Files');
  lines.push('');
  if (packageJsonFiles.length) {
    lines.push('### Node.js (package.json)');
    lines.push('');
    for (const f of packageJsonFiles) lines.push(`- ${path.relative(cds.root, f)}`);
    lines.push('');
  }
  if (pomXmlFiles.length) {
    lines.push('### Java (pom.xml)');
    lines.push('');
    for (const f of pomXmlFiles) lines.push(`- ${path.relative(cds.root, f)}`);
    lines.push('');
  }
}

const SECTION_ORDER = [
  'CDS – Improved Checks',
  'Changes to Runtime',
  'Non-Breaking Changes',
  'Flags Entirely Removed',
  'Java / Spring Boot Migration',
];

function appendAnalysis(lines, ctx) {
  if (!ctx.analysis) return;
  if (ctx.analysis.error) { lines.push(`> Error: ${ctx.analysis.error}`); lines.push(''); return; }

  const findings = ctx.analysis.findings || [];
  if (findings.length === 0) { lines.push('## Code Analysis'); lines.push(''); lines.push('No issues found.'); lines.push(''); return; }

  const bySection = groupBySection(findings);
  const orderedSections = SECTION_ORDER.filter(s => bySection.has(s));
  for (const s of bySection.keys()) {
    if (!orderedSections.includes(s)) orderedSections.push(s);
  }

  appendToc(lines, orderedSections, bySection);
  appendSummaryTables(lines, orderedSections, bySection);
  appendDetails(lines, orderedSections, bySection, ctx);
}

function groupBySection(findings) {
  const map = new Map();
  for (const f of findings) {
    const section = f.capireSection || 'Other';
    if (!map.has(section)) map.set(section, []);
    map.get(section).push(f);
  }
  for (const [, group] of map) {
    group.sort((a, b) => (a.group || '').localeCompare(b.group || ''));
  }
  return map;
}

function sectionSlug(section) {
  return 'sec-' + section.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

function appendToc(lines, orderedSections, bySection) {
  lines.push('## Table of Contents');
  lines.push('');
  for (const section of orderedSections) {
    const group = bySection.get(section);
    const totalMatches = group.reduce((sum, f) => sum + f.matches.length, 0);
    lines.push(`- [${section}](#${sectionSlug(section)}) (${group.length} rule(s), ${totalMatches} match(es))`);
    for (const f of group) {
      lines.push(`  - ${f.title} (${f.matches.length})`);
    }
  }
  lines.push('');
}

function appendSummaryTables(lines, orderedSections, bySection) {
  lines.push('## Summary');
  lines.push('');
  for (const section of orderedSections) {
    const group = bySection.get(section);
    lines.push(`<a id="${sectionSlug(section)}"></a>`);
    lines.push('');
    lines.push(`### ${section}`);
    lines.push('');
    lines.push('| Migration | Findings |');
    lines.push('|---|---|');
    for (const f of group) {
      lines.push(`| [${f.title}](#${f.ruleId}) | ${f.matches.length} |`);
    }
    lines.push('');
  }
}

function appendDetails(lines, orderedSections, bySection, ctx) {
  lines.push('## Details');
  lines.push('');
  for (const section of orderedSections) {
    const findings = bySection.get(section);
    let i = 0;
    while (i < findings.length) {
      const f = findings[i];
      if (f.groupTitle) {
        const grouped = [];
        const groupId = f.group;
        while (i < findings.length && findings[i].group === groupId) {
          grouped.push(findings[i]);
          i++;
        }
        appendGroupedFindings(lines, grouped, f.groupTitle, ctx);
      } else {
        appendFinding(lines, f, ctx);
        i++;
      }
    }
  }
}

function appendGroupedFindings(lines, findings, groupTitle, ctx) {
  lines.push(`### ${groupTitle}`);
  lines.push('');
  for (const finding of findings) {
    lines.push(`<a id="${finding.ruleId}"></a>`);
    lines.push('');
    lines.push(`#### ${finding.title}`);
    lines.push('');
    appendFindingBody(lines, finding, ctx);
  }
}

function demoteHeadings(text) {
  return text.replace(/^(#{1,4}) /gm, (_, hashes) => '#'.repeat(hashes.length + 2) + ' ');
}

function appendFinding(lines, finding, ctx) {
  lines.push(`<a id="${finding.ruleId}"></a>`);
  lines.push('');
  lines.push(`### ${finding.title}`);
  lines.push('');
  appendFindingBody(lines, finding, ctx);
}

function appendFindingBody(lines, finding, ctx) {
  if (finding.capireAnchor) {
    lines.push(`[View on cap.cloud.sap](${finding.capireAnchor})`);
    lines.push('');
  }
  if (finding.body) {
    lines.push(demoteHeadings(finding.body.trim()));
    lines.push('');
  }
  if (finding.coverage === 'incomplete') {
    lines.push('> Additional occurrences may exist. Manual review recommended.');
    lines.push('');
  }
  lines.push(`**${finding.matches.length} match(es):**`);
  lines.push('');
  appendMatchList(lines, finding, ctx);
  lines.push('');
}

function appendMatchList(lines, finding, ctx) {
  for (const m of finding.matches) {
    if (m.source === 'openrewrite') {
      const suffix = ctx.shouldFix ? '(auto-fixed)' : '(auto-fixable)';
      if (m.file) {
        const loc = m.line != null ? `${m.file}:${m.line}${m.col != null ? ':' + m.col : ''}` : m.file;
        const href = m.line != null ? `../${m.file}#L${m.line}` : `../${m.file}`;
        lines.push(`- [${loc}](${href}) ${suffix}`);
      } else {
        lines.push(`- ${suffix} \u2013 no specific locations available`);
      }
    } else if (m.file === '<cds env>') {
      const context = m.context ? ` \u2013 \`${m.context.trim()}\`` : '';
      const note = valueStatusNote(m, finding);
      lines.push(`- cds env (line ${m.line})${context}${note}`);
    } else {
      const loc = m.line != null ? `${m.file}:${m.line}${m.col != null ? ':' + m.col : ''}` : m.file;
      const href = m.line != null ? `../${m.file}#L${m.line}` : `./${m.file}`;
      const context = m.context ? ` \u2013 \`${m.context.trim()}\`` : '';
      const note = valueStatusNote(m, finding);
      lines.push(`- [${loc}](${href})${context}${note}`);
    }
  }
}

function appendManualReview(lines, ctx) {
  const rules = ctx.analysis?.manualReviewRules || [];
  if (rules.length === 0) return;
  lines.push('## Manual Review Recommended');
  lines.push('');
  lines.push('The following rules could not be fully covered by structural pattern matching.');
  lines.push('No findings were detected, but manual verification is recommended.');
  lines.push('');
  lines.push('---');
  lines.push('');
  for (const rule of rules) {
    lines.push(`### ${rule.title}`);
    lines.push('');
    lines.push(rule.body ? demoteHeadings(rule.body.trim()) : `*No additional details available for \`${rule.ruleId}\`.*`);
    lines.push('');
  }
}

function appendWarnings(lines, ctx) {
  const warnings = ctx.analysis?.warnings || [];
  if (warnings.length === 0) return;
  lines.push('## Analysis Warnings');
  lines.push('');
  lines.push('The following issues occurred during analysis (some findings may be incomplete):');
  lines.push('');
  for (const w of warnings) lines.push(`- ${w}`);
  lines.push('');
}

function writeFindings(ctx, outputDir) {
  const output = buildFindingsOutput(ctx);
  const yaml = serializeToYaml(output);
  cds.utils.fs.writeFileSync(path.join(outputDir, FINDINGS_FILE), yaml);
}

function buildFindingsOutput(ctx) {
  const output = {
    version: '1.0',
    project: {
      root: cds.root,
      languages: ctx.analysis.languages || [],
    },
    rulesScanned: ctx.analysis.rulesScanned || 0,
    compilerRan: ctx.analysis.compilerRan || false,
    findings: (ctx.analysis.findings || []).map(f => ({
      ruleId: f.ruleId,
      title: f.title,
      scope: f.scope,
      group: f.group,
      groupTitle: f.groupTitle || null,
      capireSection: f.capireSection || null,
      guidance: f.guidance,
      body: f.body || null,
      capireAnchor: f.capireAnchor || null,
      compilerDetects: f.compilerDetects || false,
      patternsComplete: f.patternsComplete || false,
      coverage: f.coverage || 'unknown',
      compatFlag: f.compatFlag || null,
      orRecipe: f.orRecipe || null,
      matches: f.matches.map(m => ({
        file: m.file || null,
        position: {
          row: m.line ?? null,
          col: m.col ?? null,
        },
        matchedText: m.context || null,
        source: m.source || null,
        valueStatus: m.valueStatus || null,
      })),
    })),
    manualReviewRules: (ctx.analysis.manualReviewRules || []).map(r => ({
      ruleId: r.ruleId,
      title: r.title,
      body: r.body || null,
    })),
  };
  if (ctx.analysis.orApplied) output.openRewriteApplied = ctx.analysis.orApplied;
  if (ctx.analysis.orSkipped) output.openRewriteSkipped = true;
  if (ctx.analysis.orFailed) output.openRewriteFailed = ctx.analysis.orFailed;
  return output;
}

function valueStatusNote(m, finding) {
  if (!m.valueStatus) return '';
  if (m.valueStatus === 'default') return ' – safe to remove, already the default';
  if (finding.capireSection === 'Flags Entirely Removed') {
    return ' – this flag no longer exists, must adapt';
  }
  return ' – kill-switch active, code must be adapted';
}

module.exports = { generate };
